import{_ as p,r as a,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"{% for %} - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Looping a collection","slug":"looping-a-collection","link":"#looping-a-collection","children":[]},{"level":2,"title":"Adding a condition","slug":"adding-a-condition","link":"#adding-a-condition","children":[]},{"level":2,"title":"The loop variable","slug":"the-loop-variable","link":"#the-loop-variable","children":[]}],"relativePath":"1.x/markup/tag-for.md","filePath":"1.x/markup/tag-for.md"}'),u={name:"1.x/markup/tag-for.md"};function r(g,n,d,k,m,w){const t=a("pre-heading"),e=a("post-heading");return o(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"{% for %}",-1)),s(e),n[1]||(n[1]=i(`<p>The <code>{% for %}</code> and <code>{% endfor %}</code> tags will loop over each value in a collection. A collection can be either an array or an object implementing the <code>Traversable</code> interface.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>You can also access both keys and values:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> key<span class="token punctuation">,</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> key <span class="token delimiter punctuation">}}</span></span>: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>If the collection is empty, you can render a replacement block by using else:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>em</span><span class="token punctuation">&gt;</span></span>There are no users found<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>em</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="looping-a-collection"><a href="#looping-a-collection" class="header-anchor">#</a> Looping a collection</h2><p>If you do need to iterate over a collection of numbers, you can use the <code>..</code> operator:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> i <span class="token operator">in</span> <span class="token number">0.</span><span class="token number">.10</span> <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> i <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The above snippet of code would print all numbers from 0 to 10.</p><p>It can also be useful with letters:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> letter <span class="token operator">in</span> <span class="token string"><span class="token punctuation">&#39;</span>a<span class="token punctuation">&#39;</span></span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token string"><span class="token punctuation">&#39;</span>z<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> letter <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <code>..</code> operator can take any expression at both sides:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> letter <span class="token operator">in</span> <span class="token string"><span class="token punctuation">&#39;</span>a<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>upper<span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token string"><span class="token punctuation">&#39;</span>z<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>upper <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> letter <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="adding-a-condition"><a href="#adding-a-condition" class="header-anchor">#</a> Adding a condition</h2><p>Unlike in PHP there is no function to <code>break</code> or <code>continue</code> in a loop, however you can still filter the collection. The following example skips all the <code>users</code> which are not active:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token keyword">if</span> user<span class="token punctuation">.</span>active <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="the-loop-variable"><a href="#the-loop-variable" class="header-anchor">#</a> The loop variable</h2><p>Inside of a <code>for</code> loop block you can access some special variables:</p><div class="table"><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>loop.index</code></td><td>The current iteration of the loop. (1 indexed)</td></tr><tr><td><code>loop.index0</code></td><td>The current iteration of the loop. (0 indexed)</td></tr><tr><td><code>loop.revindex</code></td><td>The number of iterations from the end of the loop (1 indexed)</td></tr><tr><td><code>loop.revindex0</code></td><td>The number of iterations from the end of the loop (0 indexed)</td></tr><tr><td><code>loop.first</code></td><td>True if first iteration</td></tr><tr><td><code>loop.last</code></td><td>True if last iteration</td></tr><tr><td><code>loop.length</code></td><td>The number of items in the collection</td></tr><tr><td><code>loop.parent</code></td><td>The parent context</td></tr></tbody></table></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> loop<span class="token punctuation">.</span>index <span class="token delimiter punctuation">}}</span></span> - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,21))])}const v=p(u,[["render",r]]);export{f as __pageData,v as default};
